public record User(String id, String name, double wpm) {

    public String initials() {
        return Arrays.stream(name.split(" "))
                .map(part -> part.substring(0, 1).toUpperCase())
                .collect(Collectors.joining());
    }
}

public static List<String> topLangs(List<Drill> drills, int limit) {
    return drills.stream()
            .filter(d -> d.accuracy() > 0.9)
            .sorted(Comparator.comparingDouble(Drill::wpm).reversed())
            .limit(limit)
            .map(Drill::lang)
            .toList();
}

