public static <K, V> Map<V, K> invert(Map<K, V> source) {
    var out = new LinkedHashMap<V, K>(source.size());
    for (Map.Entry<K, V> entry : source.entrySet()) {
        out.put(entry.getValue(), entry.getKey());
    }
    return out;
}

public record Money(long cents, String currency) {

    public Money {
        if (cents < 0) {
            throw new IllegalArgumentException("cents must be positive");
        }
    }

    @Override
    public String toString() {
        return "%d.%02d %s".formatted(cents / 100, cents % 100, currency);
    }
}

public static <T> Map<String, List<T>> groupBy(
        List<T> items, Function<T, String> key) {
    return items.stream()
            .collect(Collectors.groupingBy(key, TreeMap::new, Collectors.toList()));
}

public sealed interface Shape permits Circle, Rect {}

public record Circle(double radius) implements Shape {}

public record Rect(double w, double h) implements Shape {}

public static double area(Shape shape) {
    return switch (shape) {
        case Circle c -> Math.PI * c.radius() * c.radius();
        case Rect r -> r.w() * r.h();
    };
}

public static List<String> readNonBlank(Path path) throws IOException {
    try (var lines = Files.lines(path, StandardCharsets.UTF_8)) {
        return lines.map(String::strip)
                .filter(Predicate.not(String::isEmpty))
                .toList();
    }
}

public final class Cache<K, V> {

    private final Map<K, V> store = new ConcurrentHashMap<>();

    public V get(K key, Function<? super K, ? extends V> loader) {
        return store.computeIfAbsent(key, loader);
    }

    public void evictIf(BiPredicate<K, V> stale) {
        store.entrySet().removeIf(e -> stale.test(e.getKey(), e.getValue()));
    }
}

public record Stat(String lang, double wpm, double accuracy) {}

public static Map<String, Double> medianWpm(List<Stat> stats) {
    return stats.stream()
            .collect(Collectors.groupingBy(
                    Stat::lang,
                    Collectors.averagingDouble(Stat::wpm)));
}

public static <T> CompletableFuture<List<T>> allOf(List<CompletableFuture<T>> futures) {
    return CompletableFuture
            .allOf(futures.toArray(CompletableFuture[]::new))
            .thenApply(ignored -> futures.stream()
                    .map(CompletableFuture::join)
                    .toList())
            .exceptionally(throwable -> {
                throw new CompletionException(throwable);
            });
}

public sealed interface Result<T> permits Result.Ok, Result.Err {

    record Ok<T>(T value) implements Result<T> {}

    record Err<T>(Exception cause) implements Result<T> {}

    static <T> Result<T> of(Callable<T> work) {
        try {
            return new Ok<>(work.call());
        } catch (Exception e) {
            return new Err<>(e);
        }
    }

    default T orElse(T fallback) {
        return this instanceof Ok<T> ok ? ok.value() : fallback;
    }
}

public static Map<String, Long> wordFrequency(Path path) throws IOException {
    try (var lines = Files.lines(path)) {
        return lines
                .flatMap(line -> Arrays.stream(line.split("\\W+")))
                .map(String::toLowerCase)
                .filter(word -> word.length() > 2)
                .collect(Collectors.groupingBy(
                        Function.identity(),
                        TreeMap::new,
                        Collectors.counting()));
    }
}

public final class DrillBuilder {

    private String lang = "rust";
    private int minutes = 10;
    private final List<String> tags = new ArrayList<>();

    public DrillBuilder lang(String value) {
        this.lang = Objects.requireNonNull(value, "lang");
        return this;
    }

    public DrillBuilder tag(String... values) {
        Collections.addAll(tags, values);
        return this;
    }

    public Drill build() {
        return new Drill(lang, minutes, List.copyOf(tags));
    }
}

public static <T, K extends Comparable<K>> Optional<T> argMax(
        Collection<? extends T> items, Function<? super T, K> score) {
    return items.stream()
            .max(Comparator.comparing(score))
            .map(Function.identity());
}

public static IntSummaryStatistics summarize(List<Drill> drills) {
    return drills.stream()
            .mapToInt(Drill::keystrokes)
            .summaryStatistics();
}
